<template><view class="ip-scene" :class="{'ip-scene-full':expanded}"><!-- #ifdef H5 --><iframe v-if="scene" ref="frame" @load="fitEmbedded" :src="scene.path" :title="name+'360度互动场景'" allow="fullscreen" allowfullscreen="true"/><button v-if="scene" class="scene-expand" @tap="expanded=!expanded">{{expanded?'退出全屏 ×':'全屏体验 ⛶'}}</button><!-- #endif --><!-- #ifndef H5 --><image v-if="scene" :src="art.src" class="ip-stage-image" mode="aspectFit"/><view v-if="scene" class="scene-native"><button class="primary" @tap="go('panorama',{story:scene.story})">进入360°互动场景</button></view><!-- #endif --><template v-if="!scene"><image :src="art.src" class="ip-stage-image" mode="aspectFit"/><view class="ip-stage-title"><text class="eyebrow">IP人物专题 / CHARACTER</text><text class="stage-name">{{name}}</text><text>从人物形象，走进有据可循的故事</text><text class="small">艺术化IP形象 · 本专题暂未配置独立360°场景</text></view></template><view v-if="!scene" class="scene-caption"><text>{{name}} · {{scene?'360°艺术化场景':'艺术化IP形象'}}</text><text>{{scene?'拖动环视 · 阅读下方史料':'非历史照片 · 人物事实见正文'}}</text></view></view></template>
<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';import {go} from '../lib/navigation.js';
defineProps({name:String,art:Object,scene:Object});const expanded=ref(false),frame=ref(null);
// #ifdef H5
function fitEmbedded(){const doc=frame.value?.contentDocument;if(!doc?.head)return;doc.defaultView.addEventListener('keydown',key);const style=doc.createElement('style');style.textContent='#experience>header,.topbar{display:none!important}#welcome article,.opening-paper{max-height:calc(100dvh - 32px);overflow-y:auto;box-sizing:border-box} @media(max-width:650px){.heading{top:18px!important;left:16px!important;max-width:calc(100% - 110px)!important}.heading h1{font-size:26px!important}.tools{top:76px!important;right:12px!important;gap:5px!important}.tools button{width:32px!important;height:32px!important;min-height:32px!important}.scene-label{top:18px!important;left:18px!important;max-width:calc(100% - 115px)!important}.scene-label h1{font-size:26px!important}.chapter-nav{top:120px!important;left:12px!important;right:12px!important}#welcome article,.opening-paper{padding:20px}#welcome h2{font-size:30px}#welcome p{font-size:14px;line-height:1.7}}';doc.head.append(style)}
let previousOverflow='';watch(expanded,v=>{if(v){previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}else document.body.style.overflow=previousOverflow});function key(e){if(e.key==='Escape')expanded.value=false}onMounted(()=>window.addEventListener('keydown',key));onBeforeUnmount(()=>{window.removeEventListener('keydown',key);if(expanded.value)document.body.style.overflow=previousOverflow});
// #endif
</script>
<style scoped>
.ip-scene{height:470px;position:relative;overflow:hidden;border:1px solid #d4bd97;border-radius:9px;background:linear-gradient(120deg,#f3e8d2,#e7e7d8)}.ip-scene iframe{display:block;width:100%;height:100%;border:0}.scene-expand{position:absolute;top:18px;right:18px;background:#fbf5e9ed;color:#982b28;padding:8px 14px;font-size:13px;z-index:4;border-radius:8px;margin:0}.ip-scene-full{position:fixed;inset:0;height:100dvh;z-index:20000;border-radius:0}.ip-stage-image{position:absolute;width:44%;height:92%;right:5%;bottom:0}.ip-stage-title{position:absolute;top:23%;left:6%;width:43%;display:flex;flex-direction:column;gap:22px;color:#354d43}.stage-name{font:48px STSong,SimSun,serif}.scene-caption{position:absolute;bottom:0;left:0;right:0;display:flex;justify-content:space-between;gap:12px;padding:10px 22px;background:#fbf5e9eb;color:#80694d;font-size:11px;pointer-events:none}.scene-native{position:absolute;left:6%;top:35%}@media(max-width:650px){.ip-scene{height:370px}.ip-scene-full{height:100dvh}.ip-stage-title{top:16%;left:6%;gap:14px;width:48%}.stage-name{font-size:30px}.ip-stage-title>text{font-size:13px}.ip-stage-title .stage-name{font-size:30px}.ip-stage-image{width:47%;right:0}.scene-caption{padding:10px;font-size:9px}.scene-expand{top:10px;right:10px;font-size:11px}}
</style>
